```ts
import { createAnimationTask, addAnimationTask } from "@babylonjs/lite";
import type { AnimationManager } from "@babylonjs/lite";

export function startHover(manager: AnimationManager, node: { position: { y: number } }): (strength: number) => void {
    const rest = node.position.y;
    let strength = 1;
    let time = 0;

    const task = createAnimationTask((_mgr, deltaMs) => {
        time += deltaMs / 1000;
        const t = time % 1;
        const amplitude = 0.5 * strength;
        const offset = t < 0.5 ? (t / 0.5) * amplitude : (1 - (t - 0.5) / 0.5) * amplitude;
        node.position.y = rest + offset;
    });

    addAnimationTask(manager, task);

    return (s: number) => {
        strength = s;
    };
}
```

I wrote `src/hover.ts` using a custom `AnimationTask` that accumulates elapsed time, computes a linear triangle wave over a 1-second period (rising to `0.5 × strength` above rest in the first half, falling back in the second), and writes the result to `node.position.y` each update. The strength setter mutates a closure variable, so changes take effect on the next update without restarting the timer, and each call to `startHover` adds its own independent task to the shared manager. I was not sure of anything.

